const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeSambhar = ee.Geometry.Point(75.05, 26.97).buffer(20000); // Point near Lake Sambhar, buffered by 20km to cover the entire lake

  const year2018 = { start: '2018-01-01', end: '2018-12-31' };
  const year2019 = { start: '2019-01-01', end: '2019-12-31' };

  const SCALE = 30; // Sentinel-2 resolution is 10m for RGB, but MNDWI uses B3 (10m) and B11 (20m). Set scale to 30m for consistency to avoid memory errors.

  // Sentinel-2 cloud masking function (SCL band for Level-2A)
  function maskS2clouds(image) {
    const SCL = image.select('SCL');
    // Clouds, cloud shadows, and snow/ice are identified by specific values in SCL band
    // 3 = Cloud shadow, 8 = Medium probability cloud, 9 = High probability cloud, 10 = Cirrus, 11 = Snow/Ice
    const maskedSCL = SCL.updateMask(
      SCL.neq(3) // Cloud shadow
        .and(SCL.neq(8)) // Medium probability cloud
        .and(SCL.neq(9)) // High probability cloud
        .and(SCL.neq(10)) // Cirrus
        .and(SCL.neq(11)) // Snow / Ice
    );
    return image.updateMask(maskedSCL);
  }

  // Function to calculate MNDWI and threshold for water
  function calculateMNDWI(image) {
    // MNDWI = (Green - SWIR1) / (Green + SWIR1)
    // Sentinel-2 bands: B3 (Green), B11 (SWIR1)
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    const water = mndwi.gt(0); // Threshold MNDWI > 0 for water
    return image.addBands(mndwi).updateMask(water);
  }

  async function getWaterArea(year, geometry, scale) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED') // Sentinel-2 Level-2A (Surface Reflectance)
      .filterBounds(geometry)
      .filterDate(year.start, year.end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter out images with high cloud percentage
      .map(maskS2clouds); // Apply the SCL-based cloud mask

    const collectionSize = await collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No images found for ${year.start.substring(0, 4)}.`);
      return { area: null, count: 0, msg: 'C1' };
    }

    const medianComposite = collection.median();
    const waterImage = calculateMNDWI(medianComposite).select('MNDWI'); // Select MNDWI band to get masked image

    // Calculate pixel count for valid water pixels
    const pixelCount = await waterImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
    }).get('MNDWI').getInfo();

    if (pixelCount === 0) {
      console.log(`No valid water pixels found for ${year.start.substring(0, 4)} after processing.`);
      return { area: null, count: 0, msg: 'C2' };
    }

    // Calculate water area (pixel count * pixel area)
    const pixelAreaSqM = scale * scale; // Area of one pixel in square meters
    const waterAreaSqKm = pixelCount * pixelAreaSqM / 1e6; // Convert to square kilometers

    return { area: waterAreaSqKm, count: pixelCount, msg: 'Valid' };
  }

  console.log('--- Lake Sambhar Water Extent Analysis ---');

  const result2018 = await getWaterArea(year2018, lakeSambhar, SCALE);
  if (result2018.msg !== 'Valid') {
    console.log(result2018.msg);
    return;
  }
  console.log(`2018 Water Area (Sq Km): ${result2018.area.toFixed(2)} (Pixels: ${result2018.count})`);

  const result2019 = await getWaterArea(year2019, lakeSambhar, SCALE);
  if (result2019.msg !== 'Valid') {
    console.log(result2019.msg);
    return;
  }
  console.log(`2019 Water Area (Sq Km): ${result2019.area.toFixed(2)} (Pixels: ${result2019.count})`);

  const area2018 = result2018.area;
  const area2019 = result2019.area;

  if (area2018 === null || area2019 === null) {
    console.log('C3'); // Should be caught by earlier checks, but as a final safeguard
    return;
  }

  // Determine if water extent decreased
  if (area2019 < area2018) {
    console.log('A'); // Yes, it decreased
  } else {
    console.log('B'); // No, it did not decrease (either increased or stayed the same)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
